class Solution {
        static int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

            public int shortestBridge(int[][] grid) {
                    int n = grid.length;

                            Queue<int[]> queue = new ArrayDeque<>();

                                    boolean flag = false;
                                            for(int i = 0; i < n; i++) {
                                                        if(flag)
                                                                        break;

                                                                                    for(int j = 0; j < n; j++) {
                                                                                                    if(grid[i][j] == 1) {
                                                                                                                        dfs(grid, i, j, queue);
                                                                                                                                            flag = true;
                                                                                                                                                                break;
                                                                                                                                                                                }
                                                                                                                                                                                            }
                                                                                                                                                                                                    }

                                                                                                                                                                                                            int dist = 0;
                                                                                                                                                                                                                    while(!queue.isEmpty()) {
                                                                                                                                                                                                                                int size = queue.size();

                                                                                                                                                                                                                                            while(size-- > 0) {
                                                                                                                                                                                                                                                            int[] curr = queue.poll();

                                                                                                                                                                                                                                                                            for(int[] dir : dirs) {
                                                                                                                                                                                                                                                                                                int x = curr[0] + dir[0];
                                                                                                                                                                                                                                                                                                                    int y = curr[1] + dir[1];

                                                                                                                                                                                                                                                                                                                                        if(x < 0 || y < 0 || x >= n || y >= n || grid[x][y] == 2)
                                                                                                                                                                                                                                                                                                                                                                continue;

                                                                                                                                                                                                                                                                                                                                                                                    if(grid[x][y] == 1)
                                                                                                                                                                                                                                                                                                                                                                                                            return dist;
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                grid[x][y] = 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    queue.offer(new int[] {x, y});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dist++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    public void dfs(int[][] grid, int i, int j, Queue<int[]> queue) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            grid[i][j] = 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    queue.offer(new int[] {i, j});

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(int[] dir : dirs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int x = i + dir[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int y = j + dir[1];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(x < 0 || y < 0 || x >= grid.length || y >= grid.length)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                continue;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(grid[x][y] == 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dfs(grid, x, y, queue);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
